(()=>{const modal=document.querySelector('.review-rest #lightbox');if(!modal)return;document.querySelectorAll('.review-rest [data-image]').forEach(button=>button.addEventListener('click',()=>{const img=modal.querySelector('img');img.src=button.dataset.image;img.alt=button.dataset.caption||'';modal.querySelector('p').textContent=button.dataset.caption||'';modal.showModal()}));modal.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',event=>{if(event.target===modal)modal.close()})})();